import{z as s,x as r,o as e,c as o,q as B,j as l,D as a,d as i,s as n,S as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"集成基线的公平比较","description":"","frontmatter":{"title":"集成基线的公平比较","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-ensemble-fair-baseline.md","filePath":"llm/rm-ensemble-fair-baseline.md","lastUpdated":1791413859000}'),d={name:"llm/rm-ensemble-fair-baseline.md"};function m(p,E,D,C,h,_){const A=r("Mermaid");return e(),o("div",null,[E[2]||(E[2]=B('<h1 id="集成基线的公平比较" tabindex="-1">集成基线的公平比较 <a class="header-anchor" href="#集成基线的公平比较" aria-label="Permalink to &quot;集成基线的公平比较&quot;">​</a></h1><div class="epigraph"><p>「集成更好」在没配平参数与数据之前是一句空话：涨的可能是那一倍参数，不是集成这件事。</p><footer>—— 集成均值是否稳定优于最佳成员见 Eisenstein 等 Helping or Herding 2023；过优化对照协议见 Gao 等 2022</footer></div><p><a href="/llm/rm-distill-cascade">上一课</a>把大 RM 的算力账算清；本课处理证明题：当你主张「集成（或任何新 RM 方案）更好」，比较本身必须成立。<a href="/llm/rm-ensembles">RM 集成与不确定性</a>讲过集成的定义与 \\(\\hat\\sigma\\) 的用途；Eisenstein 等 2023 的批评要在这里展开成方法：集成的均值并不稳定优于最佳单成员，很多「涨点」换个基线就消失。本课写公平比较的配平清单——同样适用于蒸馏、新损失、新配方的一切「我的 RM 更好」主张。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RM 比较的自欺有固定套路：拿 \\(n\\) 模型集成对比 1 个单模型，涨点来自 \\(n\\) 倍参数；拿双倍数据训的新方案对比旧配方，涨点来自数据不是方案；拿训练集附近的持有对算准确率，涨点是捷径的一致化。每一种都通过了「有数字」的检验，没有一种回答了「这个方案本身的贡献」。Eisenstein 等 2023 的多组实验说明：集成均值在分布内的分辨力常不高于把同样预算给最佳单成员，可靠收益在不确定性信号与分布外稳健，不在点估计涨分。不这么做会错在哪：为集成维护 \\(n\\) 份训练与推理，上线后发现不如单模型加大一档，沉没成本已堆满一个季度。</p><p><span class="marginnote">代入一个数：拿 8 个 7B 模型的集成对比 1 个 7B 单模型，涨了两分——先别高兴，这局对比的总参数是 56B 对 7B，八倍。公平的对照是把 56B 训成一个模型（或共享底座的多头）。不补这组对照，你证明的只是「更多参数有用」，这条路预训练侧早就证明过了。</span></p><h3 id="配平清单" tabindex="-1">配平清单 <a class="header-anchor" href="#配平清单" aria-label="Permalink to &quot;配平清单&quot;">​</a></h3><p>公平比较至少配平四轴。参数轴：\\(n\\) 成员集成的对照物是同总参数的单模型（更大的一个）或共享底座的多头，而不是最小的那个单模型。数据轴：各成员的数据份额加总等于基线的数据总量；「集成加数据」的主张要拆成两个单变量消融。标注轴：若新方案需要额外标注（如强度档、仲裁），成本记入方案。评测轴：金标固定——held-out 人评加一个与各方都独立的大 RM，评测集在方案设计前冻结。四轴之外还有时间轴：算力与墙钟时间也是资源，报告写清哪些配平了，比假装全配平诚实。</p>',8)),(e(),l(t,null,{default:a(()=>[n(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E4%B8%BB%E5%BC%A0%EF%BC%9A%E6%96%B9%E6%A1%88%20X%20%E4%BC%98%E4%BA%8E%E5%9F%BA%E7%BA%BF%22%5D%20--%3E%20BAL%5B%22%E9%85%8D%E5%B9%B3%EF%BC%9A%E5%8F%82%E6%95%B0%20%2F%20%E6%95%B0%E6%8D%AE%20%2F%20%E6%A0%87%E6%B3%A8%20%2F%20%E8%AF%84%E6%B5%8B%E9%9B%86%22%5D%0A%20%20BAL%20--%3E%20A1%5B%22%E6%B6%88%E8%9E%8D%E4%B8%80%EF%BC%9A%E5%8F%AA%E6%8D%A2%E6%96%B9%E6%A1%88%22%5D%0A%20%20BAL%20--%3E%20A2%5B%22%E6%B6%88%E8%9E%8D%E4%BA%8C%EF%BC%9A%E5%8F%AA%E5%8A%A0%E8%B5%84%E6%BA%90%22%5D%0A%20%20A1%20--%3E%20GOLD%5B%22%E9%87%91%E6%A0%87%E8%AF%84%E6%B5%8B%EF%BC%9A%E4%BA%BA%E8%AF%84%20%2B%20%E7%8B%AC%E7%AB%8B%E5%A4%A7%20RM%22%5D%0A%20%20A2%20--%3E%20GOLD%0A%20%20GOLD%20--%3E%20DEC%7B%22%E6%96%B9%E6%A1%88%20X%20%E4%BB%8D%E8%83%9C%3F%22%7D%0A%20%20DEC%20--%3E%7C%E6%98%AF%7C%20ADOPT%5B%22%E9%87%87%E7%BA%B3%E5%B9%B6%E8%AE%B0%E5%BD%95%E6%B6%88%E8%9E%8D%22%5D%0A%20%20DEC%20--%3E%7C%E5%90%A6%7C%20REJ%5B%22%E6%B6%A8%E7%82%B9%E5%BD%92%E5%B1%9E%E8%B5%84%E6%BA%90%EF%BC%8C%E9%80%80%E5%9B%9E%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指标层同样要换。全局比较准确率换成两件套：分域准确率（配比课的下限口径）加过优化曲线——按 Gao 等 2022 的协议，对每个方案跑等预算的小规模 RL，画金标对步数曲线，比拐点位置与曲线下面积。「RM 好不好」的最终定义不是「分得对不对」，是「拿它优化策略，策略变好多少、多久变坏」：一个 RewardBench 低两分但拐点晚一倍的 RM，工程价值更高。</p><p><span class="marginnote">术语翻译：「过优化曲线的拐点」就是策略开始变坏的时刻。做法是拿 RM 去跑小规模 RL，每隔几步停下来用金标（人评或独立大 RM）给策略的真实表现打分：前期金标随训练上涨，越过某个点后不升反降——那个掉头处就是拐点，来得越晚说明这个 RM 越「经得住优化」。</span>成员多样性的消融也在此列：种子、数据、初始化多样性各贡献多少，决定买集成的钱该花在哪种多样性上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么集成均值常输给大单模型：集成提高估计的稳定性（方差下降），不改变假设空间（偏差不变）；同样参数给单模型，容量变大、偏差可降。RM 任务里偏差恰是大头——捷径、覆盖空洞都是偏差病，方差药治不了。集成的真收益在两处：分歧 \\(\\hat\\sigma\\) 当免费的不确定性量（单模型要靠 dropout 或多头近似），以及成员独立失效时的表决稳健性。WARM 类权重平均（上一课提过）是谱系的另一端：不训 \\(n\\) 份模型，靠损失面平坦性用一份权重近似均值行为——它的存在说明集成的可取部分可在参数空间里复制，也支持「均值涨点多数来自方差」的判断。</p>',5)),(e(),l(t,null,{default:a(()=>[n(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22RM%20%E6%80%BB%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20BIAS%5B%22%E5%81%8F%E5%B7%AE%EF%BC%9A%E5%81%87%E8%AE%BE%E7%A9%BA%E9%97%B4%E5%AD%A6%E9%94%99%E6%96%B9%E5%90%91%22%5D%0A%20%20ERR%20--%3E%20VAR%5B%22%E6%96%B9%E5%B7%AE%EF%BC%9A%E8%AE%AD%E7%BB%83%E9%9A%8F%E6%9C%BA%E6%80%A7%E7%9A%84%E6%8A%96%E5%8A%A8%22%5D%0A%20%20ENS%5B%22%E9%9B%86%E6%88%90%E5%9D%87%E5%80%BC%22%5D%20--%3E%7C%22%E5%8F%AA%E8%83%BD%E9%99%8D%22%7C%20VAR%0A%20%20BIG%5B%22%E5%90%8C%E5%8F%82%E6%95%B0%E5%A4%A7%E5%8D%95%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%7C%22%E8%83%BD%E9%99%8D%22%7C%20BIAS%0A%20%20BIAS%20--%3E%20SICK%5B%22%E6%8D%B7%E5%BE%84%E4%B8%8E%E8%A6%86%E7%9B%96%E7%A9%BA%E6%B4%9E%E9%83%BD%E6%98%AF%E5%81%8F%E5%B7%AE%E7%97%85%22%5D%0A%20%20SICK%20--%3E%20NOGAIN%5B%22%E6%95%85%E9%9B%86%E6%88%90%E7%9A%84%E7%82%B9%E4%BC%B0%E8%AE%A1%E5%88%86%E8%BE%A8%E5%8A%9B%E5%B8%B8%E4%B8%8D%E6%B6%A8%22%5D%0A%20%20VAR%20--%3E%20GAIN%5B%22%E9%9B%86%E6%88%90%E7%9A%84%E7%9C%9F%E6%94%B6%E7%9B%8A%EF%BC%9A%E5%88%86%E6%AD%A7%E4%BF%A1%E5%8F%B7%E4%B8%8E%E8%A1%A8%E5%86%B3%E7%A8%B3%E5%81%A5%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">直觉类比：偏差是尺子刻度画错了，方差是每次读数手都在抖。让 8 个人各读一次取平均，能抹平手抖（方差），但尺子刻度错了（偏差），平均多少次都还是错的。RM 的捷径与覆盖空洞属于刻度问题——这正是集成均值在分辨力上赢不了大单模型的原因。</span></p><p><span class="marginnote">Coste 等 2023 的集成主张与 Eisenstein 等 2023 的质疑并不矛盾：前者展示集成降低过优化（用 σ 与保守均值），后者质疑均值在分辨力上胜过最佳成员。引用任何一方时先写清「在哪个指标上」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>公平比较做不到完备：金标有人评噪声（一致性课口径适用），独立大 RM 也有偏置，配平四轴仍可能有隐藏轴（数据管线与分词版本）。可执行的底线是「可复核」：另一组人拿配平清单能重跑出同一结论，比追求完美配平实际。也要防反向错误：不能拿「比较难做公平」拒绝比较——不配平的涨点进了决策，整个团队的算力跟着错。本课的方法论在下一课的公共基准上会遇到更强的约束：基准分高与下游好之间的落差，比内部比较更隐蔽。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不配平的比较是资源声明不是方法主张：参数、数据、标注、评测集四轴是底线。</li><li>Eisenstein 等 2023 的教训：集成均值在分辨力上不稳定优于最佳成员，收益在 \\(\\hat\\sigma\\) 与稳健性。</li><li>终局指标是过优化曲线：等预算 RL 的金标拐点，比比较准确率更接近「RM 的用途」。</li><li>消融要单变量化，报告写清配平了什么、没配平什么。</li><li>出处：Eisenstein 等 Helping or Herding，2023；Coste 等 2023；Gao、Schulman、Hilton 2022。</li></ul>',6))])}const R=s(d,[["render",m]]);export{c as __pageData,R as default};
